describe('Notification Auto-Dismissal', () => {
  beforeEach(() => {
    cy.visit('/notifications');
  });

  it('should auto-dismiss notifications after 5 seconds', () => {
    // Intercept the notification API call
    cy.intercept('GET', '/api/notifications').as('getNotifications');
    cy.wait('@getNotifications');

    // Verify notifications are displayed
    cy.get('[data-testid="notification-item"]').should('be.visible');
    cy.get('[data-testid="notification-text"]').should('contain', 'New message received');

    // Verify notification has a dismiss timer
    cy.get('[data-testid="notification-item"]').should('have.class', 'notification-active');

    // Wait for the auto-dismiss timer (5 seconds)
    cy.wait(5100);

    // Verify notification is dismissed
    cy.get('[data-testid="notification-item"]').should('not.exist');
    cy.get('[data-testid="notification-list"]').should('be.visible');
  });

  it('should not auto-dismiss notifications when user interacts with them', () => {
    // Intercept the notification API call
    cy.intercept('GET', '/api/notifications').as('getNotifications');
    cy.wait('@getNotifications');

    // Verify notification is displayed
    cy.get('[data-testid="notification-item"]').should('be.visible');

    // User hovers over the notification
    cy.get('[data-testid="notification-item"]').trigger('mouseenter');

    // Verify notification remains visible after hover
    cy.get('[data-testid="notification-item"]').should('be.visible');

    // Wait for the auto-dismiss timer (5 seconds)
    cy.wait(5100);

    // Verify notification is still visible because user interacted with it
    cy.get('[data-testid="notification-item"]').should('be.visible');

    // User clicks on the notification
    cy.get('[data-testid="notification-item"]').click();

    // Verify notification is dismissed after click
    cy.get('[data-testid="notification-item"]').should('not.exist');
  });
});
